/bin/bash -lc "python - <<'PY'
import json
from pathlib import Path
fields=json.loads(Path('run_trace/galaxy_tool_schema_005/fields.json').read_text())
for f in fields:
    aw=f.get('active_when') or []
    if any(a.get('value')=='long_branch_score' for a in aw) or f.get('path','').startswith('operation|input_mode'):
        if any(a.get('value')=='long_branch_score' for a in aw):
            print(json.dumps(f, indent=2))
PY"

